        try:
            msg = json.loads(line)
            role = msg.get('message', {}).get('role', '')
            content_parts = msg.get('message', {}).get('content', [])
            for part in content_parts:
                if isinstance(part, dict):
                    if 'text' in part:
                        text = part['text']
